 $("#pageContent").innerHTML=head("People & staff","Employee directory and controlled ERP account permissions.",'<button class="primary-btn" data-action="new-staff">+ Add staff record</button>'+assign)+panel("Staff directory",table(["Employee No.","Staff member","Department","Position","Employment","Joined","Base salary","Status","Actions"],d.map(x=>'<tr><td>'+esc(x.employee_no)+'</td><td><b>'+esc(x.full_name)+'</b><br><small>'+esc(x.email||"")+'</small></td><td>'+esc(x.department||"—")+'</td><td>'+esc(x.position||"—")+'</td><td>'+esc(x.employment_type||"—")+'</td><td>'+esc(x.date_joined||"—")+'</td><td>'+money(x.base_salary)+'</td><td>'+pill(x.status)+'</td><td><button class="link-btn" data-action="edit-old" data-type="staff" data-id="'+esc(x.id)+'">Edit</button></td></tr>').join("")))+panel("ERP users and access",table(["Name","Email","Role","Status"],u.map(x=>'<tr><td>'+esc(x.full_name)+'</td><td>'+esc(x.email)+'</td><td>'+esc(labels[x.role]||x.role)+'</td><td>'+pill(x.status)+'</td></tr>').join("")));
