async function finance(){
 const [d,i,s]=await Promise.all([rows("erp_finance_entries","entry_date"),rows("erp_invoices"),rows("erp_students")]);
 const inc=d.filter(x=>x.entry_type==="income"&&x.status==="posted").reduce((a,x)=>a+Number(x.amount),0),out=d.filter(x=>x.entry_type==="expense"&&x.status==="posted").reduce((a,x)=>a+Number(x.amount),0),bal=i.reduce((a,x)=>a+Math.max(0,Number(x.amount_due)-Number(x.amount_paid)),0);
 const ledger=table(["Date","Reference","Type","Category","Description","Amount","Status","Actions"],d.map(x=>'<tr><td>'+esc(x.entry_date)+'</td><td>'+esc(x.reference||"—")+'</td><td>'+esc(x.entry_type)+'</td><td>'+esc(x.category)+'</td><td>'+esc(x.description||"—")+'</td><td>'+money(x.amount)+'</td><td>'+pill(x.status)+'</td><td><button class="link-btn" data-action="edit-old" data-type="entry" data-id="'+esc(x.id)+'">Edit</button></td></tr>').join(""));
 const invoices=table(["Invoice","Learner","Amount due","Paid","Due date","Status","Actions"],i.map(x=>{const st=s.find(y=>y.id===x.student_id);return '<tr><td>'+esc(x.invoice_no)+'</td><td>'+esc(st?st.first_name+" "+st.last_name:"—")+'</td><td>'+money(x.amount_due)+'</td><td>'+money(x.amount_paid)+'</td><td>'+esc(x.due_date||"—")+'</td><td>'+pill(x.status)+'</td><td><button class="link-btn" data-action="edit-old" data-type="invoice" data-id="'+esc(x.id)+'">Edit</button></td></tr>';}).join(""));
 $("#pageContent").innerHTML=head("Finance","Track income, expenditure, learner invoices and institutional balances.",'<button class="primary-btn" data-action="new-entry">+ Record transaction</button><button class="secondary-btn" data-action="new-invoice">Create invoice</button>')+'<div class="stats-grid">'+stat("Posted income",money(inc),"Income entries")+stat("Posted expenses",money(out),"Expense entries")+stat("Net position",money(inc-out),"Income less expenses")+stat("Outstanding invoices",money(bal),"Unpaid learner balance")+'</div>'+panel("Transaction ledger",ledger)+panel("Issued learner invoices",invoices);
}
