async function settings(){
 let audit=[];
 if(["super_admin","admin"].includes(profile.role)){try{audit=await rows("erp_audit_logs");}catch(_){}}
 const auditRows=audit.slice(0,12).map(x=>'<tr><td>'+esc(x.created_at?.replace("T"," ").slice(0,19)||"—")+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.entity)+'</td><td>'+esc(x.entity_id||"")+'</td></tr>').join("");
 const adminTools=profile.role==="super_admin"?'<button class="secondary-btn" data-page="staff">Manage ERP users & permissions</button>':"";
 $("#pageContent").innerHTML=head("Settings & access","Manage your account, access controls and administrative oversight.",adminTools)+panel("Your ERP account",'<p><b>'+esc(profile.full_name)+'</b></p><p class="muted">'+esc(profile.email)+'</p><p>Role: '+pill(labels[profile.role]||profile.role)+'</p><p class="muted">ETHAN ERP operates with its own authentication, database and deployment. ETHAN LMS remains a separate learning product.</p>')+(["super_admin","admin"].includes(profile.role)?panel("Recent audit activity",table(["Time","Action","Module","Record ID"],auditRows)):"");
}

