function exportGenericCsv(key,ix){
 const section=genericModules[key]?.sections[ix];if(!section)return;
 const data=cache[section.table]||[];
 const quote=v=>{let x=String(v===null||v===undefined?"":v);if(/^\s*[=+\-@]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};
 const lines=[section.columns.map(c=>c[0]).map(quote).join(",")];
 for(const row of data)lines.push(section.columns.map(c=>{let v=c[2]==="variance"?Number(row.budget_amount||0)-Number(row.actual_amount||0):row[c[1]];if(c[2]==="money")v=Number(v||0);if(c[1]==="reconciled")v=v?"Yes":"No";return quote(v);}).join(","));
 const blob=new Blob(["\uFEFF"+lines.join("\r\n")],{type:"text/csv;charset=utf-8"});
 const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="ethan-erp-"+section.table+".csv";document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);
}
function genericFormat(row,col){
 const v=row[col[1]];
 if(col[1]==="student_id"){
  const list=cache.erp_students||cache.erp_student_case_directory||[];
  const st=list.find(x=>x.id===v);
  if(st)return esc((st.admission_no?st.admission_no+" · ":"")+(st.first_name||"")+" "+(st.last_name||""));
 }
 if(col[1]==="project_id"){const pr=(cache.erp_projects||[]).find(x=>x.id===v);if(pr)return esc(pr.project_name);}
 if(col[1]==="bank_account_id"){const ba=(cache.erp_bank_accounts||[]).find(x=>x.id===v);if(ba)return esc(ba.bank_name+" · "+ba.account_name);}
 if(col[1]==="programme_code"){const pr=(cache.erp_programmes||[]).find(x=>x.code===v);if(pr)return esc(pr.name);}

 if(col[2]==="money")return money(v);
 if(col[2]==="date")return v?esc(String(v).slice(0,10)):"—";
 if(col[2]==="variance")return money(Number(row.budget_amount||0)-Number(row.actual_amount||0));
 if(col[1]==="reconciled")return v?"Yes":"No";
 return v===null||v===undefined||v===""?"—":esc(v);
}
function genericActions(key,ix,section,row){
 if(section.table==="erp_approval_requests"){
  if(row.status!=="pending")return "—";
  if(!["super_admin","admin"].includes(profile.role)&&profile.role!==row.approver_role)return "Assigned to "+esc(labels[row.approver_role]||row.approver_role||"an authorised approver");
  return '<button class="link-btn" data-action="decide-approval" data-decision="approved" data-id="'+esc(row.id)+'">Approve</button> <button class="link-btn" data-action="decide-approval" data-decision="rejected" data-id="'+esc(row.id)+'">Reject</button>';
 }
 if(section.table==="erp_journal_entries"){
  if(!["super_admin","admin","finance"].includes(profile.role))return "—";
  if(row.reversal_of)return "Reversal journal";
  if((cache.erp_journal_entries||[]).some(x=>x.reversal_of===row.id))return "Reversed";
  return '<button class="link-btn" data-action="reverse-journal" data-id="'+esc(row.id)+'">Reverse journal</button>';
 }
 if(section.table==="erp_payment_receipts"){
  if(row.status!=="recorded")return esc(row.status||"—");
  if(!["super_admin","admin","finance"].includes(profile.role))return "—";
  return '<button class="link-btn" data-action="reverse-payment" data-id="'+esc(row.id)+'">Reverse receipt</button>';
 }
 let html='<button class="link-btn" data-action="edit-generic" data-module="'+key+'" data-section="'+ix+'" data-id="'+esc(row.id)+'">Edit</button>';
 if(section.table==="erp_applications"&&row.status==="accepted")html+=' <button class="link-btn" data-action="convert-application" data-id="'+esc(row.id)+'">Enrol learner</button>';
 return html;
}
function genericTableHtml(key,ix,section,data){
 const hasActions=!section.readOnly||section.table==="erp_approval_requests"||section.table==="erp_payment_receipts"||section.table==="erp_journal_entries";
 const heads=section.columns.map(c=>c[0]).concat(hasActions?["Actions"]:[]);
 const body=data.map(row=>"<tr>"+section.columns.map(c=>"<td>"+genericFormat(row,c)+"</td>").join("")+(hasActions?'<td>'+genericActions(key,ix,section,row)+'</td>':"")+"</tr>").join("");
 return '<div class="table-toolbar"><input id="gsearch_'+key+'_'+ix+'" placeholder="Search '+esc(section.title.toLowerCase())+'..."></div><div id="gtable_'+key+'_'+ix+'">'+table(heads,body)+"</div>";
}
async function genericPage(key){
 if(key==="accounting"||key==="crm"||key==="procurement") {try{await rows("erp_chart_accounts");}catch(_){}}

 const cfg=genericModules[key];if(!cfg)return;
 let html="";
 for(let i=0;i<cfg.sections.length;i++){
  const s=cfg.sections[i],d=await rows(s.table,s.order||"created_at");
  for(const f of s.fields){if(f.relation&&!cache[f.relation.table])await rows(f.relation.table);}
  html+=panel(s.title,genericTableHtml(key,i,s,d),(s.button?'<button class="primary-btn" data-action="new-generic" data-module="'+key+'" data-section="'+i+'">+ '+esc(s.button)+'</button>':"")+'<button class="secondary-btn" data-action="export-generic" data-module="'+key+'" data-section="'+i+'">Export CSV</button>');
 }
 $("#pageContent").innerHTML=head(cfg.title,cfg.desc)+html;
 for(let i=0;i<cfg.sections.length;i++){
  const s=cfg.sections[i],search=$("#gsearch_"+key+"_"+i);
  if(search)search.oninput=()=>{
   const q=search.value.toLowerCase(),d=(cache[s.table]||[]).filter(row=>s.columns.some(c=>String(row[c[1]]??"").toLowerCase().includes(q)));
   const hasActions=!s.readOnly||s.table==="erp_approval_requests"||s.table==="erp_payment_receipts"||s.table==="erp_journal_entries";
   const body=d.map(row=>"<tr>"+s.columns.map(c=>"<td>"+genericFormat(row,c)+"</td>").join("")+(hasActions?'<td>'+genericActions(key,i,s,row)+'</td>':"")+"</tr>").join("");
   $("#gtable_"+key+"_"+i).innerHTML=table(s.columns.map(c=>c[0]).concat(hasActions?["Actions"]:[]),body);
  };
 }
}
function genericFieldHtml(field,value){
 const v=value===null||value===undefined?(field.defaultToday?today():""):String(value),req=field.required?"required":"";
 if(field.options||field.relation){
  let opts=field.options||[];
  if(field.relation){opts=(cache[field.relation.table]||[]).map(x=>[x[field.relation.value],(field.relation.prefix&&x[field.relation.prefix]?x[field.relation.prefix]+" · ":"")+x[field.relation.label]]);}
  return '<label>'+esc(field.label)+'<select name="'+field.name+'" '+req+'>'+'<option value="">Select / not assigned</option>'+opts.map(o=>'<option value="'+esc(o[0])+'" '+(String(o[0])===v?"selected":"")+'>'+esc(o[1])+'</option>').join("")+'</select></label>';
 }
 if(field.type==="textarea")return '<label>'+esc(field.label)+'<textarea name="'+field.name+'" '+req+'>'+esc(v)+'</textarea></label>';
 const min=field.type==="number"?' min="0" step="0.01"':"";
 return '<label>'+esc(field.label)+'<input name="'+field.name+'" type="'+(field.type||"text")+'" value="'+esc(v)+'" '+req+min+'></label>';
}
function openGenericForm(key,ix,row){
 const cfg=genericModules[key];if(!cfg)return;const s=cfg.sections[ix];if(!s)return;
 if(s.table==="erp_journal_entries"&&!row){
  const accounts=(cache.erp_chart_accounts||[]).filter(a=>a.status==="active");
  if(accounts.length<2){toast("Add at least two active chart-of-account records before posting a journal.",true);return;}
  const opts=accounts.map(a=>'<option value="'+esc(a.account_code)+'">'+esc(a.account_code+" — "+a.account_name)+'</option>').join("");
  const lines=[1,2,3,4].map(i=>'<section class="panel"><b>Journal line '+i+'</b><div class="two-col"><label>Account<select name="account_'+i+'"><option value="">Select account</option>'+opts+'</select></label><label>Description<input name="line_desc_'+i+'"></label></div><div class="two-col"><label>Debit (NGN)<input type="number" min="0" step="0.01" name="debit_'+i+'"></label><label>Credit (NGN)<input type="number" min="0" step="0.01" name="credit_'+i+'"></label></div></section>').join("");
  modal("Post balanced journal",fld("journal_no","Journal number")+fld("entry_date","Entry date","date",true,'value="'+today()+'"')+'<label>Description<textarea name="description" required></textarea></label>'+lines,async fd=>{
   const journalLines=[];
   for(let i=1;i<=4;i++){
    const account=String(fd.get("account_"+i)||"").trim(),debit=Number(fd.get("debit_"+i)||0),credit=Number(fd.get("credit_"+i)||0),description=String(fd.get("line_desc_"+i)||"").trim();
    if(!account&&!debit&&!credit)continue;
    if(!account||((debit>0)===(credit>0)))throw Error("Each used journal line needs an account and either a debit or a credit, not both.");
    journalLines.push({account_code:account,debit,credit,description});
   }
   await rpc("post_erp_journal",{p_journal_no:String(fd.get("journal_no")||"").trim(),p_entry_date:String(fd.get("entry_date")||today()),p_description:String(fd.get("description")||"").trim(),p_lines:journalLines});
  });
  return;
 }
 const fields=(s.table==="erp_inventory_items"&&row)?s.fields.filter(f=>f.name!=="quantity_on_hand"):s.fields;
 const body=fields.map(f=>genericFieldHtml(f,row?row[f.name]:undefined)).join("");
 modal((row?"Edit ":"")+s.title,body,async fd=>{
  const payload={};
  for(const f of fields){
   const v=String(fd.get(f.name)||"").trim();
   if(f.type==="number")payload[f.name]=v===""?0:Number(v);
   else if(f.type==="date")payload[f.name]=v||null;
   else if(f.name==="reconciled")payload[f.name]=v==="true";
   else payload[f.name]=v||null;
  }
  if(s.table==="erp_payroll_items")payload.net_pay=Math.max(0,Number(payload.basic_salary||0)+Number(payload.allowances||0)-Number(payload.deductions||0));
  if(s.table==="erp_student_enrolments"&&payload.programme_code){const selected=(cache.erp_programmes||[]).find(x=>x.code===payload.programme_code);payload.programme_name=selected?.name||payload.programme_code;}
  if(s.table==="erp_customer_invoices"||s.table==="erp_supplier_bills")payload.total_amount=Number(payload.subtotal||0)+Number(payload.tax_amount||0);
  if(s.table==="erp_inventory_movements"&&!row){
   await rpc("record_erp_inventory_movement",{p_item_id:payload.item_id,p_type:payload.movement_type,p_quantity:payload.quantity,p_date:payload.movement_date||today(),p_reference:payload.reference,p_notes:payload.notes});
  }else if(s.table==="erp_payment_receipts"&&!row){
   await rpc("record_erp_payment_receipt",{p_receipt_no:payload.receipt_no,p_invoice_no:payload.invoice_no,p_payer_name:payload.payer_name,p_payment_date:payload.payment_date||today(),p_amount:payload.amount,p_method:payload.method,p_reference:payload.reference});
  }else{
   const result=row?await client.from(s.table).update(payload).eq("id",row.id):await client.from(s.table).insert(payload);
   if(result.error)throw result.error;
  }
 });
}

function fld(n,l,t,req,attrs){return '<label>'+l+'<input name="'+n+'" type="'+(t||"text")+'" '+(req===false?"":"required ")+(attrs||"")+'></label>';}
function sel(n,l,opts){return '<label>'+l+'<select name="'+n+'">'+opts.map(x=>'<option value="'+esc(x[0])+'">'+esc(x[1])+'</option>').join("")+'</select></label>';}
function val(fd,k){return String(fd.get(k)||"").trim();}
function today(){return new Date().toISOString().slice(0,10);}
function modal(title,body,save){$("#modalRoot").innerHTML='<div class="modal-backdrop" data-close><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>'+title+'</h3><button class="icon-btn" data-close>✕</button></div><form id="modalForm" class="modal-form">'+body+'<div class="modal-actions"><button type="button" class="secondary-btn" data-close>Cancel</button><button type="submit" class="primary-btn">Save record</button></div></form></div></div>';$("#modalForm").onsubmit=async e=>{e.preventDefault();const b=$('button[type="submit"]',e.currentTarget);b.disabled=true;try{await save(new FormData(e.currentTarget));$("#modalRoot").innerHTML="";toast("Record saved.");await navigate(current);}catch(x){toast(x.message||"Could not save record.",true);b.disabled=false;}};}
function populateRecordForm(html,row){
 let out=html;
 out=out.replace(/(<input\b[^>]*\bname="([^"]+)"[^>]*)(>)/g,(match,before,key,close)=>{
  let value=row[key]===null||row[key]===undefined?"":String(row[key]);
  const type=(before.match(/\btype="([^"]+)"/)||[])[1]||"text";
  if(type==="date")value=value.slice(0,10);
  if(type==="datetime-local")value=value.slice(0,16);
  before=before.replace(/\svalue="[^"]*"/g,"");
  return before+' value="'+esc(value)+'"'+close;
 });
 out=out.replace(/(<textarea\b[^>]*\bname="([^"]+)"[^>]*>)[\s\S]*?(<\/textarea>)/g,(match,open,key,close)=>open+esc(row[key]===null||row[key]===undefined?"":row[key])+close);
 out=out.replace(/(<select\b[^>]*\bname="([^"]+)"[^>]*>)([\s\S]*?)(<\/select>)/g,(match,open,key,options,close)=>{
  const current=String(row[key]===null||row[key]===undefined?"":row[key]);
  const updated=options.replace(/<option\b([^>]*)value="([^"]*)"([^>]*)>/g,(m,before,value,after)=>{
   const attrs=(before+" "+after).replace(/\sselected(?:="selected")?/g,"");
   return '<option'+attrs+' value="'+value+'"'+(String(value)===current?' selected':"")+'>';
  });
  return open+updated+close;
 });
 return out;
}
