document.addEventListener("click",async e=>{const at=e.target.closest("[data-auth-tab]");if(at){showAuth(at.dataset.authTab);return;}const pg=e.target.closest("[data-page]");if(pg){await navigate(pg.dataset.page);$("#sidebar").classList.remove("open");return;}if(e.target.closest("[data-close]")){$("#modalRoot").innerHTML="";return;}const a=e.target.closest("[data-action]")?.dataset.action;if(a==="refresh")await navigate(current);if(a==="new-student")createForm("student");if(a==="new-programme")createForm("programme");if(a==="new-staff")createForm("staff");if(a==="new-entry")createForm("entry");if(a==="new-invoice"){await rows("erp_students");createForm("invoice");}if(a==="new-attendance"){await rows("erp_students");createForm("attendance");}if(a==="new-event")createForm("event");if(a==="new-record"){await rows("erp_students");createForm("record");}if(a==="new-certificate"){await rows("erp_students");createForm("certificate");}if(a==="new-announcement")createForm("announcement");if(a==="promote")await promote();if(a==="new-generic"||a==="edit-generic"){const b=e.target.closest("[data-action]"),k=b.dataset.module,ix=Number(b.dataset.section),s=genericModules[k]?.sections[ix],r=b.dataset.id?(cache[s.table]||[]).find(x=>x.id===b.dataset.id):null;await openGenericForm(k,ix,r||null);}if(a==="export-generic"){const b=e.target.closest("[data-action]");exportGenericCsv(b.dataset.module,Number(b.dataset.section));}if(a==="convert-application"){const b=e.target.closest("[data-action]");modal("Convert accepted application to learner",fld("admission_no","New admission number")+fld("level","Level","text",false),async fd=>{await rpc("convert_erp_application",{p_application_id:b.dataset.id,p_admission_no:String(fd.get("admission_no")||"").trim(),p_level:String(fd.get("level")||"").trim()||null});});}if(a==="decide-approval"){const b=e.target.closest("[data-action]");modal(b.dataset.decision==="approved"?"Approve request":"Reject request",'<label>Decision notes<textarea name="decision_notes" required></textarea></label>',async fd=>{await rpc("decide_erp_approval",{p_request_id:b.dataset.id,p_decision:b.dataset.decision,p_notes:String(fd.get("decision_notes")||"").trim()});});}if(a==="reverse-payment"){const b=e.target.closest("[data-action]");modal("Reverse payment receipt",'<label>Reversal reason<textarea name="reason" required></textarea></label>',async fd=>{await rpc("reverse_erp_payment_receipt",{p_receipt_id:b.dataset.id,p_reason:String(fd.get("reason")||"").trim()});});}if(a==="reverse-journal"){const b=e.target.closest("[data-action]");modal("Reverse posted journal",fld("reversal_no","Reversal journal number")+fld("reversal_date","Reversal date","date",true,'value="'+today()+'"')+'<label>Reason<textarea name="reason" required></textarea></label>',async fd=>{await rpc("reverse_erp_journal",{p_journal_id:b.dataset.id,p_reversal_no:String(fd.get("reversal_no")||"").trim(),p_reversal_date:String(fd.get("reversal_date")||today()),p_reason:String(fd.get("reason")||"").trim()});});}});
$("#signinForm").addEventListener("submit",async e=>{e.preventDefault();setmsg("#signinMessage","Signing in...");try{const r=await client.auth.signIn.email({email:$("#signinEmail").value.trim(),password:$("#signinPassword").value});if(r.error)throw r.error;if(!r.data?.user)throw Error("Sign-in failed.");session=r.data.session;profile=await ensureProfile(r.data.user);if(profile.status!=="active")throw Error("This ERP account is inactive.");openApp();}catch(x){setmsg("#signinMessage",x.message||"Sign-in failed.",true);}});
$("#signupForm").addEventListener("submit",async e=>{e.preventDefault();if($("#signupPassword").value!==$("#confirmPassword").value){setmsg("#signupMessage","Passwords do not match.",true);return;}setmsg("#signupMessage","Creating account...");try{const name=$("#firstName").value.trim()+" "+$("#lastName").value.trim(),r=await client.auth.signUp.email({email:$("#signupEmail").value.trim(),password:$("#signupPassword").value,name:name,callbackURL:location.origin+"/"});if(r.error)throw r.error;if(!r.data?.user)throw Error("Account was not created.");const s=await client.auth.getSession();if(s.error)throw s.error;if(!s.data?.session)throw Error("Account created. Please sign in.");session=s.data.session;await rpc("ensure_erp_profile",{p_full_name:name,p_phone:$("#signupPhone").value.trim()});profile=await ensureProfile(r.data.user);openApp();}catch(x){setmsg("#signupMessage",x.message||"Account creation failed.",true);}});
$("#forgotBtn").onclick=async()=>{const email=$("#signinEmail").value.trim();if(!email){toast("Enter your account email first.",true);return;}try{const r=await client.auth.requestPasswordReset({email,redirectTo:location.origin+"/"});if(r.error)throw r.error;toast("Password reset request sent.");}catch(x){toast(x.message||"Password reset failed.",true);}};
$("#logoutBtn").onclick=async()=>{try{await client.auth.signOut();}catch(_){}session=null;profile=null;showAuth("signin");};
$("#menuBtn").onclick=()=>$("#sidebar").classList.toggle("open");$("#refreshBtn").onclick=()=>navigate(current);boot();